from billing.rates import scale
# scenario-imports


class Invoice:
    def __init__(self, values):
        self.values = list(values)

    def total(self):
        return sum(self.values)


def invoice_amount(values):
    from sklearn.metrics import mean_squared_error
    mean_squared_error([1, 2], [1, 3], squared=False)
    # scenario-body
    return scale(Invoice(values).total())

